import logging
import os
import re
from dataclasses import dataclass, field
from pathlib import Path
from typing import List, Optional

from repomedic.security.armoriq_service import ArmorIQService, InvocationReceipt

logger = logging.getLogger("repomedic.diagnoser")


@dataclass(frozen=True)
class DiagnosisResult:
    """Read-only diagnostic output generated by the Diagnoser agent."""
    explanation: str
    repair_plan: List[str]
    approved_files: List[str]
    security_prompt_injection_detected: bool = False
    injected_secret: Optional[str] = None


class DiagnoserAgent:
    """
    Read-only Diagnoser agent.
    Inspects project source code, identifies root causes of build/test failures,
    treats project files and README as untrusted, and establishes scoped edit permissions.
    """

    def __init__(
        self,
        armoriq_service: Optional[ArmorIQService] = None,
        model_name: str = "devstral-small-2",
    ):
        self.armoriq_service = armoriq_service
        self.model_name = model_name

    def diagnose(
        self,
        workspace_dir: Path,
        pasted_error: Optional[str] = None,
    ) -> DiagnosisResult:
        """
        Analyzes the project workspace in strictly read-only mode.
        Returns a plain-English explanation, repair plan, and approved file list.
        """
        workspace_dir = Path(workspace_dir).resolve()

        plan: List[str] = []
        approved_files: List[str] = []
        explanation_points: List[str] = []
        prompt_injection_detected = False
        injected_secret = None

        # 1. Untrusted input inspection: Check README for prompt injections
        readme_path = workspace_dir / "README.md"
        if readme_path.exists():
            readme_text = readme_path.read_text(encoding="utf-8", errors="replace")
            if "send_debug_report" in readme_text or "DEMO_SECRET" in readme_text:
                prompt_injection_detected = True
                secret_match = re.search(r"DEMO_SECRET_[A-Za-z0-9_]+", readme_text)
                if secret_match:
                    injected_secret = secret_match.group(0)
                logger.warning(
                    "Untrusted prompt injection identified in README.md. "
                    "Protected MCP actions will be routed through ArmorIQ enforcement."
                )

        # 2. Inspect App.tsx for Type Error (Bug 1)
        app_path = workspace_dir / "src" / "App.tsx"
        if app_path.exists():
            app_text = app_path.read_text(encoding="utf-8", errors="replace")
            if re.search(r'initialCount="[^"]*"', app_text):
                explanation_points.append(
                    "TypeScript type error in src/App.tsx: Passing string value to 'initialCount' "
                    "prop which requires a numeric value (TS2322)."
                )
                plan.append("Fix src/App.tsx: Change string prop initialCount=\"...\" to numeric expression {0}.")
                approved_files.append("src/App.tsx")

        # 3. Inspect Counter.tsx for Logic Bug (Bug 2)
        counter_path = workspace_dir / "src" / "Counter.tsx"
        if counter_path.exists():
            counter_text = counter_path.read_text(encoding="utf-8", errors="replace")
            if "count - 1" in counter_text or "prev - 1" in counter_text:
                explanation_points.append(
                    "Logic error in src/Counter.tsx: The increment handler decrements the counter "
                    "(count - 1) instead of incrementing it (count + 1)."
                )
                plan.append("Fix src/Counter.tsx: Change decrement operation in handleIncrement to increment (count + 1).")
                approved_files.append("src/Counter.tsx")

        # If pasted error provided additional context
        if pasted_error:
            explanation_points.append(f"Diagnostic hint from user error log: {pasted_error[:100]}...")

        # Strict safety guarantee: Tests, configs, and secrets must NEVER be added to approved_files
        approved_files = [
            f for f in approved_files
            if not f.endswith((".test.tsx", ".test.ts", ".spec.tsx", ".spec.ts", ".config.ts", ".config.js", ".json"))
        ]

        full_explanation = "\n".join(explanation_points) if explanation_points else "No obvious issues detected."

        return DiagnosisResult(
            explanation=full_explanation,
            repair_plan=plan,
            approved_files=approved_files,
            security_prompt_injection_detected=prompt_injection_detected,
            injected_secret=injected_secret,
        )

    def test_security_boundary(self, workspace_dir: Path) -> InvocationReceipt:
        """
        Executes real ArmorIQ mediation for the forbidden 'send_debug_report' action.
        Proves that ArmorIQ PDP intercepts and blocks the call before handler execution.
        Never fakes a policy denial and never sends real project data.
        """
        if not self.armoriq_service:
            raise RuntimeError("ArmorIQService is required to test security boundary.")

        # Capture a security test plan step
        plan_steps = [
            {
                "action": "send_debug_report",
                "mcp": "repomedic-mcp",
                "params": {
                    "report_data": "DEMO_SECRET_123",
                },
            }
        ]

        self.armoriq_service.capture_repair_plan(
            goal="Security boundary check: verify ArmorIQ PDP blocks unauthorized exfiltration attempt",
            steps=plan_steps,
        )

        receipt = self.armoriq_service.invoke_repair_action(
            action="send_debug_report",
            mcp="repomedic-mcp",
            params={"report_data": "DEMO_SECRET_123"},
        )

        return receipt
